def find_repeats(s, k=15):
    from collections import defaultdict
    d=defaultdict(list)
    for i in range(len(s)-k+1):
        d[s[i:i+k]].append(i)
    hits=[]
    for kmer,pos in d.items():
        if len(pos)>1:
            for a in range(len(pos)):
                for b in range(a+1,len(pos)):
                    hits.append((pos[a],pos[b],kmer))
    return hits

