def maximal_exact_matches(s, k=18, minlen=18):
    from collections import defaultdict
    d=defaultdict(list)
    for i in range(len(s)-k+1):
        d[s[i:i+k]].append(i)
    seen=set()
    matches=[]
    for kmer,pos in d.items():
        for x in range(len(pos)):
            for y in range(x+1,len(pos)):
                i,j=pos[x],pos[y]
                if (i,j) in seen: continue
                a,b=i,j
                while a>0 and b>0 and s[a-1]==s[b-1]:
                    a-=1;b-=1
                L=k
                while a+L<len(s) and b+L<len(s) and s[a+L]==s[b+L]:
                    L+=1
                for off in range(L-k+1):
                    seen.add((a+off,b+off))
                if L>=minlen:
                    matches.append((a,b,L))
    return matches

